    // Test that the visitor can visit both trade types
    swap.accept(visitor);
    bond.accept(visitor);

    std::cout << "Total notional: " << visitor.total() << std::endl;

    // Test try_accept functionality
    trade::Swap swap2(2000000.0, 0.03);
